CREATE TABLE knowledge_proposals(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,resolution_id TEXT NOT NULL REFERENCES conversation_resolutions(id),message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,category_id TEXT NOT NULL REFERENCES knowledge_categories(id),locale TEXT NOT NULL,source_domain TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,article_id TEXT NOT NULL UNIQUE,state TEXT NOT NULL CHECK(state IN ('draft','rejected','published')),reviewed_by TEXT,review_reason TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE knowledge_corrections(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES knowledge_proposals(id) ON DELETE CASCADE,resolution_id TEXT NOT NULL REFERENCES conversation_resolutions(id),created_at INTEGER NOT NULL,UNIQUE(proposal_id,resolution_id));
CREATE TRIGGER knowledge_proposal_erasure BEFORE UPDATE OF metadata_json ON contacts WHEN coalesce(json_extract(NEW.metadata_json,'$.is_erasing'),0)=1 OR coalesce(json_extract(NEW.metadata_json,'$.is_erased'),0)=1 BEGIN
 DELETE FROM knowledge_articles WHERE id IN (SELECT article_id FROM knowledge_proposals WHERE conversation_id IN (SELECT id FROM conversations WHERE contact_id=NEW.id AND project_id=NEW.project_id));
 DELETE FROM knowledge_proposals WHERE conversation_id IN (SELECT id FROM conversations WHERE contact_id=NEW.id AND project_id=NEW.project_id);
END;
CREATE TABLE knowledge_proposal_reviews(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES knowledge_proposals(id) ON DELETE CASCADE,state TEXT NOT NULL CHECK(state IN ('approved','rejected')),reason TEXT NOT NULL,reviewer_id TEXT NOT NULL,created_at INTEGER NOT NULL);
